    base_num INT := 55525; -- Número inicial del consecutivo  
    nuevo_numero TEXT;  
BEGIN  
    WHILE i < 40000 LOOP  
        -- Generar el nuevo número consecutivo  
        nuevo_numero := 'FCCP-' || (base_num + i);

        -- Incrementar el contador  
        i := i + 1;  
    END LOOP;  
END $$;

